import { fileURLToPath } from "node:url";
import { defineConfig } from "vite";
import { tanstackStart } from "@tanstack/react-start/plugin/vite";
import react from "@vitejs/plugin-react";

const repoRoot = fileURLToPath(new URL("..", import.meta.url));

// Plugin order matters: tanstackStart() must come before react().
export default defineConfig({
  plugins: [tanstackStart(), react()],
  resolve: {
    alias: {
      "@": fileURLToPath(new URL("./src", import.meta.url)),
      // The optimizer and the targets calculator live at the repo root and are
      // regenerated by scripts/build_js.py. Alias rather than copy, so the site
      // always uses the file the build pipeline and the tests use.
      "@solver": fileURLToPath(new URL("../src/lib", import.meta.url)),
    },
  },
  server: {
    // ../src/lib sits outside this Vite root; let the dev server read it.
    fs: { allow: [repoRoot] },
  },
});
